  'ls.back': 'Volver', 'ls.start': 'Empezar', 'ls.toGame': 'Volver a la partida', 'ls.toLessons': 'Volver a las lecciones', 'ls.retry': 'Repetir', 'ls.nextStep': 'Siguiente paso', 'ls.hint': 'Pista', 'ls.next': 'Siguiente', 'ls.result': 'Resultado', 'ls.quit': 'Salir',
