// puzzles v2: intro with the move count
(() => {
const S = {
  ja: { 'pz.startTurn2': '下の列があなたです。基準は{n}手（もう一回も1手と数えます）。正解から外れても相手が応じて続けられますが、明らかなミスはその場で失敗です。', 'pz.startEnd2': '下の列があなたです。相手は最善で応じます。基準は{n}手。小さなずれは続けられますが、勝敗が悪くなる手や6粒以上損する手は即失敗です。' },
  en: { 'pz.startTurn2': 'You are the bottom row. The puzzle takes {n} moves (each extra turn counts as a move). Off the solution, the opponent answers and you play on; a clear mistake fails at once.', 'pz.startEnd2': 'You are the bottom row. The opponent answers perfectly. The puzzle takes {n} moves. Small slips play on; a move that worsens the result or loses 6+ seeds fails at once.' },
  zh: { 'pz.startTurn2': '下排是你。基准为{n}手（再走一次也算1手）。偏离正解时对手会应对并继续；明显的失误立即失败。', 'pz.startEnd2': '下排是你。对手以最佳应对。基准为{n}手。小偏差可继续；使胜负变差或损失6颗以上的手立即失败。' },
  ko: { 'pz.startTurn2': '아래 줄이 나입니다. 기준은 {n}수(한 번 더도 1수로 셉니다). 정답에서 벗어나도 상대가 응수하며 계속할 수 있지만, 명백한 실수는 즉시 실패입니다.', 'pz.startEnd2': '아래 줄이 나입니다. 상대는 최선으로 응수합니다. 기준은 {n}수. 작은 실수는 계속되지만 승패가 나빠지거나 6개 이상 손해 보는 수는 즉시 실패입니다.' },
  es: { 'pz.startTurn2': 'Eres la fila inferior. El problema son {n} jugadas (cada turno extra cuenta). Si te desvías, el rival responde y sigues; un error claro falla al instante.', 'pz.startEnd2': 'Eres la fila inferior. El rival responde perfecto. El problema son {n} jugadas. Los pequeños desvíos siguen; una jugada que empeora el resultado o pierde 6+ semillas falla al instante.' },
  fr: { 'pz.startTurn2': 'Vous êtes la rangée du bas. Le problème se joue en {n} coups (chaque tour supplémentaire compte). Hors solution, l’adversaire répond et vous continuez ; une erreur nette échoue aussitôt.', 'pz.startEnd2': 'Vous êtes la rangée du bas. L’adversaire répond parfaitement. Le problème se joue en {n} coups. Les petits écarts continuent ; un coup qui aggrave le résultat ou perd 6 graines ou plus échoue aussitôt.' },
  pt: { 'pz.startTurn2': 'Você é a fileira de baixo. O problema tem {n} lances (cada turno extra conta). Fora da solução, o rival responde e você continua; um erro claro falha na hora.', 'pz.startEnd2': 'Você é a fileira de baixo. O rival responde perfeitamente. O problema tem {n} lances. Pequenos desvios continuam; um lance que piora o resultado ou perde 6+ sementes falha na hora.' },
  de: { 'pz.startTurn2': 'Du bist die untere Reihe. Die Aufgabe hat {n} Züge (jeder Extrazug zählt). Abseits der Lösung antwortet der Gegner und du spielst weiter; ein klarer Fehler scheitert sofort.', 'pz.startEnd2': 'Du bist die untere Reihe. Der Gegner antwortet perfekt. Die Aufgabe hat {n} Züge. Kleine Abweichungen laufen weiter; ein Zug, der das Ergebnis verschlechtert oder 6+ Samen kostet, scheitert sofort.' },
  hi: { 'pz.startTurn2': 'आप नीचे की पंक्ति हैं। पहेली {n} चालों की है (हर अतिरिक्त बारी एक चाल)। हल से हटने पर विरोधी जवाब देता है और आप खेलते रहते हैं; साफ़ गलती पर तुरंत असफल।', 'pz.startEnd2': 'आप नीचे की पंक्ति हैं। विरोधी सबसे अच्छा जवाब देता है। पहेली {n} चालों की है। छोटी चूक पर खेल जारी रहता है; परिणाम बिगाड़ने या 6+ बीज गँवाने वाली चाल पर तुरंत असफल।' },
  ar: { 'pz.startTurn2': 'أنت الصف السفلي. اللغز من {n} نقلات (كل دور إضافي نقلة). إن حدت عن الحل يرد الخصم وتواصل؛ الخطأ الواضح يفشل فوراً.', 'pz.startEnd2': 'أنت الصف السفلي. يرد الخصم بإتقان. اللغز من {n} نقلات. الانحرافات الصغيرة تستمر؛ النقلة التي تسوء النتيجة أو تخسر 6 بذور أو أكثر تفشل فوراً.' },
  ru: { 'pz.startTurn2': 'Вы — нижний ряд. Ходов в задаче: {n} (каждый доп. ход считается). Вне решения соперник отвечает и игра идёт дальше; явная ошибка — сразу провал.', 'pz.startEnd2': 'Вы — нижний ряд. Соперник отвечает идеально. Ходов в задаче: {n}. Мелкие промахи — игра идёт дальше; ход, ухудшающий результат или теряющий 6+ семян, — сразу провал.' },
  'zh-TW': { 'pz.startTurn2': '下排是你。基準為{n}手（再走一次也算1手）。偏離正解時對手會應對並繼續；明顯的失誤立即失敗。', 'pz.startEnd2': '下排是你。對手會完美應對。基準為{n}手。小失誤可以繼續；讓結果變差或損失6顆以上的著法立即失敗。' },
  id: { 'pz.startTurn2': 'Kamu baris bawah. Teka-teki ini {n} langkah (tiap jalan lagi dihitung satu langkah). Di luar solusi, lawan membalas dan kamu lanjut; kesalahan jelas langsung gagal.', 'pz.startEnd2': 'Kamu baris bawah. Lawan membalas sempurna. Teka-teki ini {n} langkah. Selip kecil tetap lanjut; langkah yang memperburuk hasil atau rugi 6+ biji langsung gagal.' },
  tr: { 'pz.startTurn2': 'Alt sıra sizsiniz. Bulmaca {n} hamle (her ekstra tur bir hamle sayılır). Çözümün dışında rakip cevap verir ve devam edersiniz; açık bir hata anında başarısızlıktır.', 'pz.startEnd2': 'Alt sıra sizsiniz. Rakip kusursuz cevap verir. Bulmaca {n} hamle. Küçük kaymalar devam eder; sonucu kötüleştiren veya 6+ taş kaybettiren hamle anında başarısızlıktır.' },
};
for (const l in S) window.I18N[l] = Object.assign(window.I18N[l] || {}, S[l]);
})();

// Intro page of the rules tutorial (RuleTour.intro): origin, history, how to win, culture. Facts kept general.
(function () {
const S = {
  ja: {"ri.t":"マンカラってどんなゲーム？","ri.origin":"アフリカ・中東など","ri.players":"2人","ri.time":"1局 5〜15分ほど","ri.hist":"マンカラは、穴に種や小石を1つずつまいていく<b>「まき遊び」</b>の仲間の総称で、世界でもっとも古いボードゲームのひとつとされます。ここで遊ぶ「カラハ」は、20世紀にアメリカで広まった遊びやすいルールです。","ri.win":"ゲームが終わったとき、<b>自分のストア（大きな穴）に種を多く集めた方の勝ち</b>です。","ri.cult":"アフリカ・中東・南アジア・東南アジアなど広い地域で、地面に掘った穴と木の実や小石でも遊ばれてきました。ガーナなどのオワレ、東アフリカのバオ、フィリピンのスンカなど、土地ごとに名前やルールが違います。"},
  en: {"ri.t":"What is Mancala?","ri.origin":"Africa, Middle East and beyond","ri.players":"2 players","ri.time":"about 5 – 15 min","ri.hist":"Mancala is the name for a whole family of <b>“sowing” games</b>, where seeds or pebbles are dropped one by one into pits. It is said to be one of the oldest board games in the world. The version here, Kalah, is an easy-to-play rule set that became popular in the United States in the 20th century.","ri.win":"When the game ends, the player with <b>more seeds in their store (the big pit) wins</b>.","ri.cult":"Across Africa, the Middle East, South and Southeast Asia it has been played even with holes dug in the ground and nuts or pebbles. Each region has its own name and rules — Oware in Ghana and nearby countries, Bao in East Africa, Sungka in the Philippines, and many more."},
  zh: {"ri.t":"播棋（曼卡拉）是什么样的游戏？","ri.origin":"非洲、中东等地","ri.players":"2人","ri.time":"一局约5～15分钟","ri.hist":"曼卡拉是把种子或小石子一颗颗撒进坑里的<b>“播棋”</b>类游戏的总称，被认为是世界上最古老的棋类游戏之一。这里玩的“卡拉哈”是20世纪在美国流行起来的简单易玩的规则。","ri.win":"游戏结束时，<b>自己的仓（大坑）里种子多的一方获胜</b>。","ri.cult":"在非洲、中东、南亚、东南亚等广大地区，人们甚至在地上挖坑、用果实或小石子来玩。加纳等地的奥瓦雷、东非的巴奥、菲律宾的松卡等，各地的名称和规则都不一样。"},
  ko: {"ri.t":"만칼라는 어떤 게임일까?","ri.origin":"아프리카·중동 등","ri.players":"2명","ri.time":"한 판 약 5~15분","ri.hist":"만칼라는 구멍에 씨앗이나 작은 돌을 하나씩 뿌려 나가는 <b>‘씨뿌리기 놀이’</b> 계열을 통틀어 부르는 이름으로, 세계에서 가장 오래된 보드게임 중 하나로 알려져 있습니다. 여기서 즐기는 ‘칼라’는 20세기에 미국에서 퍼진 쉬운 규칙입니다.","ri.win":"게임이 끝났을 때 <b>자기 창고(큰 구멍)에 씨앗을 더 많이 모은 쪽이 승리</b>합니다.","ri.cult":"아프리카·중동·남아시아·동남아시아 등 넓은 지역에서 땅에 판 구멍과 나무 열매나 작은 돌로도 즐겨 왔습니다. 가나 등의 오와레, 동아프리카의 바오, 필리핀의 숭카처럼 지역마다 이름과 규칙이 다릅니다."},
  es: {"ri.t":"¿Qué es el mancala?","ri.origin":"África, Oriente Medio y más","ri.players":"2 jugadores","ri.time":"unos 5 – 15 min","ri.hist":"Mancala es el nombre de toda una familia de <b>juegos de «siembra»</b>, en los que se dejan caer semillas o piedrecitas una a una en hoyos. Se considera uno de los juegos de tablero más antiguos del mundo. La versión de aquí, el kalah, es un reglamento sencillo que se popularizó en Estados Unidos en el siglo XX.","ri.win":"Al terminar la partida, <b>gana quien tenga más semillas en su almacén (el hoyo grande)</b>.","ri.cult":"En África, Oriente Medio y el sur y sudeste de Asia se ha jugado incluso con hoyos cavados en la tierra y frutos secos o piedras. Cada región tiene su nombre y sus reglas: oware en Ghana y alrededores, bao en África oriental, sungka en Filipinas y muchos más."},
  fr: {"ri.t":"Qu’est-ce que le mancala ?","ri.origin":"Afrique, Moyen-Orient et ailleurs","ri.players":"2 joueurs","ri.time":"env. 5 – 15 min","ri.hist":"Mancala désigne toute une famille de <b>jeux de « semailles »</b>, où l’on dépose des graines ou des cailloux un par un dans des trous. On le considère comme l’un des plus anciens jeux de plateau du monde. La version proposée ici, le kalah, est une règle simple devenue populaire aux États-Unis au XXe siècle.","ri.win":"À la fin de la partie, <b>celui qui a le plus de graines dans son magasin (le grand trou) gagne</b>.","ri.cult":"En Afrique, au Moyen-Orient, en Asie du Sud et du Sud-Est, on y joue même avec des trous creusés dans le sol et des noix ou des cailloux. Chaque région a son nom et ses règles : l’awalé (oware) en Afrique de l’Ouest, le bao en Afrique de l’Est, le sungka aux Philippines, et bien d’autres."},
  pt: {"ri.t":"O que é o mancala?","ri.origin":"África, Oriente Médio e além","ri.players":"2 jogadores","ri.time":"cerca de 5 – 15 min","ri.hist":"Mancala é o nome de toda uma família de <b>jogos de “semeadura”</b>, em que sementes ou pedrinhas são colocadas uma a uma em covas. É considerado um dos jogos de tabuleiro mais antigos do mundo. A versão daqui, o kalah, é uma regra fácil que se popularizou nos Estados Unidos no século XX.","ri.win":"No fim da partida, <b>vence quem tiver mais sementes no seu depósito (a cova grande)</b>.","ri.cult":"Na África, no Oriente Médio e no Sul e Sudeste da Ásia, joga-se até com covas cavadas no chão e castanhas ou pedrinhas. Cada região tem seu nome e suas regras: oware em Gana e arredores, bao na África Oriental, sungka nas Filipinas e muitos outros."},
  de: {"ri.t":"Was ist Mancala?","ri.origin":"Afrika, Naher Osten u. a.","ri.players":"2 Spieler","ri.time":"etwa 5 – 15 Min.","ri.hist":"Mancala ist der Name einer ganzen Familie von <b>„Säspielen“</b>, bei denen Samen oder Steinchen einzeln in Mulden gelegt werden. Es gilt als eines der ältesten Brettspiele der Welt. Die Version hier, Kalaha, ist eine einfache Regel, die im 20. Jahrhundert in den USA populär wurde.","ri.win":"Am Ende der Partie <b>gewinnt, wer mehr Samen in seinem Speicher (der großen Mulde) hat</b>.","ri.cult":"In Afrika, im Nahen Osten sowie in Süd- und Südostasien wird es sogar mit in den Boden gegrabenen Mulden und Nüssen oder Steinchen gespielt. Jede Region hat eigene Namen und Regeln — Oware in Ghana und Umgebung, Bao in Ostafrika, Sungka auf den Philippinen und viele mehr."},
  hi: {"ri.t":"मनकाला कैसा खेल है?","ri.origin":"अफ़्रीका, मध्य-पूर्व आदि","ri.players":"2 खिलाड़ी","ri.time":"एक खेल लगभग 5 – 15 मिनट","ri.hist":"मनकाला उन <b>“बुआई” वाले खेलों</b> के पूरे परिवार का नाम है, जिनमें बीज या कंकड़ एक-एक करके गड्ढों में डाले जाते हैं। इसे दुनिया के सबसे पुराने बोर्ड गेम में से एक माना जाता है। यहाँ खेला जाने वाला “कलाह” एक आसान नियम है जो 20वीं सदी में अमेरिका में लोकप्रिय हुआ।","ri.win":"खेल ख़त्म होने पर <b>जिसके भंडार (बड़े गड्ढे) में ज़्यादा बीज हों, वह जीतता है</b>।","ri.cult":"अफ़्रीका, मध्य-पूर्व, दक्षिण और दक्षिण-पूर्व एशिया में इसे ज़मीन में खोदे गड्ढों और बीजों या कंकड़ों से भी खेला जाता रहा है। हर इलाक़े के अपने नाम और नियम हैं — घाना आदि में ओवारे, पूर्वी अफ़्रीका में बाओ, फ़िलीपींस में सुंका, और भी बहुत।"},
  ar: {"ri.t":"ما هي لعبة المنقلة؟","ri.origin":"أفريقيا والشرق الأوسط وغيرها","ri.players":"لاعبان","ri.time":"نحو 5 – 15 دقيقة","ri.hist":"المنقلة اسم لعائلة كاملة من <b>ألعاب «البذر»</b>، تُوضع فيها البذور أو الحصى واحدة تلو الأخرى في حفر. وتُعدّ من أقدم ألعاب الطاولة في العالم. أما النسخة هنا، كالاه، فهي قواعد سهلة انتشرت في الولايات المتحدة في القرن العشرين.","ri.win":"عند نهاية اللعبة <b>يفوز من جمع بذوراً أكثر في مخزنه (الحفرة الكبيرة)</b>.","ri.cult":"في أفريقيا والشرق الأوسط وجنوب آسيا وجنوب شرقها لُعبت حتى بحفر في الأرض وبالبذور أو الحصى. ولكل منطقة اسمها وقواعدها: أواري في غانا وما حولها، وباو في شرق أفريقيا، وسونكا في الفلبين، وغيرها كثير."},
  ru: { "ri.t": "Что такое манкала?", "ri.origin": "Африка, Ближний Восток и не только", "ri.players": "2 игрока", "ri.time": "около 5 – 15 мин", "ri.hist": "Манкала — название целого семейства <b>«посевных» игр</b>, где семена или камешки раскладывают по одному в лунки. Её считают одной из старейших настольных игр в мире. Здесь вы играете в калах — простой вариант правил, ставший популярным в США в XX веке.", "ri.win": "Когда игра заканчивается, <b>побеждает тот, у кого больше семян в амбаре (большой лунке)</b>.", "ri.cult": "В Африке, на Ближнем Востоке, в Южной и Юго-Восточной Азии в неё играли даже на ямках в земле с орехами или камешками. В каждом регионе своё название и свои правила: оваре в Гане и соседних странах, бао в Восточной Африке, сунгка на Филиппинах и многие другие." },
  'zh-TW': { "ri.t": "播棋（曼卡拉）是什麼樣的遊戲？", "ri.origin": "非洲、中東等地", "ri.players": "2人", "ri.time": "一局約5～15分鐘", "ri.hist": "曼卡拉是把種子或小石子一顆顆放進坑裡的<b>「播種遊戲」</b>家族的總稱，據說是世界上最古老的棋盤遊戲之一。這裡玩的卡拉（Kalah）是20世紀在美國流行起來、容易上手的規則。", "ri.win": "對局結束時，<b>倉（大坑）裡種子多的一方獲勝</b>。", "ri.cult": "在非洲、中東、南亞和東南亞，人們甚至在地上挖洞、用果實或石子來玩。各地有各自的名稱和規則——迦納一帶的奧瓦雷（Oware）、東非的巴奧（Bao）、菲律賓的松卡（Sungka）等等。" },
  id: { "ri.t": "Apa itu mancala?", "ri.origin": "Afrika, Timur Tengah, dan lainnya", "ri.players": "2 pemain", "ri.time": "sekitar 5 – 15 menit", "ri.hist": "Mancala adalah nama untuk satu keluarga besar <b>permainan “menyebar biji”</b>, tempat biji atau kerikil dijatuhkan satu per satu ke lubang. Konon ini salah satu permainan papan tertua di dunia. Versi di sini, Kalah, adalah aturan mudah yang populer di Amerika Serikat pada abad ke-20.", "ri.win": "Saat permainan selesai, <b>pemain dengan biji lebih banyak di lumbungnya (lubang besar) menang</b>.", "ri.cult": "Di Afrika, Timur Tengah, Asia Selatan dan Tenggara, permainan ini dimainkan bahkan dengan lubang di tanah dan kacang atau kerikil. Tiap daerah punya nama dan aturannya sendiri — Oware di Ghana dan sekitarnya, Bao di Afrika Timur, Sungka di Filipina, congklak di Indonesia, dan banyak lagi." },
  tr: { "ri.t": "Mangala nedir?", "ri.origin": "Afrika, Orta Doğu ve ötesi", "ri.players": "2 oyuncu", "ri.time": "yaklaşık 5 – 15 dk", "ri.hist": "Mancala, taş veya tohumların kuyulara birer birer bırakıldığı koca bir <b>“dağıtma” oyunları</b> ailesinin adıdır; Türkiye'de mangala olarak bilinir. Dünyanın en eski masa oyunlarından biri olduğu söylenir. Buradaki Kalah, 20. yüzyılda ABD'de yaygınlaşan, oynaması kolay bir kural setidir.", "ri.win": "Oyun bittiğinde <b>hazinesinde (büyük kuyu) daha çok taş olan kazanır</b>.", "ri.cult": "Afrika, Orta Doğu, Güney ve Güneydoğu Asya'da toprağa kazılmış çukurlar ve fındık ya da çakıl taşlarıyla bile oynanmıştır. Her bölgenin kendi adı ve kuralları vardır: Gana ve çevresinde Oware, Doğu Afrika'da Bao, Filipinler'de Sungka, Türkiye'de Mangala ve daha niceleri." },
};
for (const l in S) window.I18N[l] = Object.assign(window.I18N[l] || {}, S[l]);
})();
